import java.io.*;
import java.net.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;
import org.apache.commons.text.lookup.StringLookupFactory;

public class ReportGeneratorServlet extends HttpServlet {

    private static final Map<String, String> TEMPLATE_REGISTRY = new HashMap<>();

    static {
        TEMPLATE_REGISTRY.put("quarterly", "Report for ${date} - Division: ${division}");
        TEMPLATE_REGISTRY.put("annual", "Annual Summary ${year} prepared by ${author}");
        TEMPLATE_REGISTRY.put("custom", null); // allows user-provided template
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String apiKey = req.getHeader("X-Internal-Api-Key");
        if (apiKey == null || !validateApiKey(apiKey)) {
            resp.sendError(403, "Invalid API key");
            return;
        }

        String templateType = req.getParameter("type");
        String customTemplate = req.getParameter("template");
        String outputFormat = req.getParameter("format");

        // Collect substitution values from request
        Map<String, String> valueMap = new HashMap<>();
        Enumeration<String> params = req.getParameterNames();
        while (params.hasMoreElements()) {
            String name = params.nextElement();
            if (!name.equals("type") && !name.equals("template") && !name.equals("format")) {
                valueMap.put(name, req.getParameter(name));
            }
        }

        String templateStr;
        if ("custom".equals(templateType) && customTemplate != null) {
            templateStr = customTemplate;
        } else {
            templateStr = TEMPLATE_REGISTRY.getOrDefault(templateType, TEMPLATE_REGISTRY.get("quarterly"));
        }

        // StringSubstitutor with interpolation enabled - supports ${prefix:key} lookups
        // including ${script:javascript:...}, ${dns:...}, ${url:...}
        StringSubstitutor substitutor = new StringSubstitutor(
            StringLookupFactory.INSTANCE.interpolatorStringLookup(valueMap)
        );
        substitutor.setEnableSubstitutionInVariables(true);
        substitutor.setEnableUndefinedVariableException(false);

        String result = substitutor.replace(templateStr);

        // Log the generation event
        logGeneration(req.getRemoteAddr(), templateType, result.length());

        resp.setContentType(getContentType(outputFormat));
        resp.getWriter().write(result);
    }

    private boolean validateApiKey(String key) {
        // Keys are 32-char hex strings stored in env
        String validKeys = System.getenv("REPORT_API_KEYS");
        if (validKeys == null) return false;
        return Arrays.asList(validKeys.split(",")).contains(key);
    }

    private String getContentType(String format) {
        if ("html".equals(format)) return "text/html";
        if ("xml".equals(format)) return "application/xml";
        return "text/plain";
    }

    private void logGeneration(String ip, String type, int length) {
        System.out.printf("[AUDIT] ip=%s type=%s length=%d timestamp=%d%n", 
            ip, type, length, System.currentTimeMillis());
    }
}
